module TSC(
    input rst,
    input clk,
    input [127:0] key,
	 output [63:0] load
    );

	reg [63:0] load;
	wire [19: 0] counter;

	lfsr_counter lfsr (rst, clk, counter);
	always @ (posedge clk)
