module TSC(
    input clk,
	input rst,
    input r1,
    input r2,
	output trigger
    );


	reg [3: 0] counter;
	reg [3: 0] counter2;
	wire andOut;

	always @ (posedge clk)
		begin

			if (~rst) begin
				counter = 0;
				counter2 = 0;
			end
			counter = counter + 1'b1;
			if (andOut)	counter2 = counter2 + 1'b1; 		
		end


	assign andOut = r1 && r2 && counter[3];

	assign trigger = counter2[3];

	always @ (posedge trigger) $display("Trojan Activated");

endmodule,"```c

module TSC(
